/*
 * Pro tips
 * - FIFO preserves job order. Keep a running sum of pages as elapsed time.
 * - After each dequeue, record the updated total, not the job size or previous total.
 * - Check a single job, equal-sized jobs, and empty input.
 * - Complexity: O(n) time and O(n) space for the queue/result. A direct prefix-sum loop avoids the queue copy.
 * - Java int sums can overflow if page totals exceed the int range; use long if larger totals are allowed.
 */

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static List<Integer> simulatePrintQueue(List<Integer> jobs) {
        Queue<Integer> queue = new ArrayDeque<>(jobs);
        List<Integer> completionTimes = new ArrayList<>();
        int currentTime = 0;

        while (!queue.isEmpty()) {
            int pages = queue.poll();
            currentTime += pages;
            completionTimes.add(currentTime);
        }

        return completionTimes;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> jobs = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        List<Integer> res = simulatePrintQueue(jobs);
        System.out.println(res.stream().map(String::valueOf).collect(Collectors.joining(" ")));
    }
}
